UPDATE iam_access_token_issuances
SET revoked_at = #{revokedAt}, revocation_reason = #{reason}
WHERE jti = #{jti} AND revoked_at IS NULL

UPDATE iam_access_token_issuances
SET revoked_at = #{revokedAt}, revocation_reason = #{reason}
WHERE kid = #{kid}
  AND expires_at + INTERVAL '30 seconds' > #{revokedAt}
  AND revoked_at IS NULL
